//@category SP11.Camera
import ghidra.app.script.GhidraScript; import ghidra.program.model.mem.Memory; import ghidra.program.model.address.Address; import java.io.*;
public class DumpQheeVmidMetadata extends GhidraScript { public void run() throws Exception {String[] a=getScriptArgs(); PrintWriter p=new PrintWriter(new FileOutputStream(a[0])); Memory m=currentProgram.getMemory(); int count=m.getInt(toAddr("001e0e00")); p.println("META_COUNT="+count); long base=0x003083c0L; for(int i=0;i<count&&i<256;i++){Address x=toAddr(Long.toHexString(base+i*20L)); int f0=m.getInt(x); int f4=m.getInt(x.add(4)); int f8=m.getInt(x.add(8)); int fc=m.getInt(x.add(12)); int f10=m.getInt(x.add(16)); p.printf("META[%d] addr=%s f0_vmid=0x%x f4=0x%x f8=0x%x fc_type=0x%x f10=0x%x%n",i,x,f0,f4,f8,fc,f10);} int acount=m.getInt(toAddr("00308744")); p.println("ALIAS_COUNT="+acount); long abase=0x0030871cL; for(int i=0;i<acount&&i<256;i++){Address x=toAddr(Long.toHexString(abase+i*8L)); int in=m.getInt(x); int out=m.getInt(x.add(4)); p.printf("ALIAS[%d] in=0x%x out=0x%x%n",i,in,out);} p.close(); }}
